function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 2 || s.length > 100000) return 's needs 2 to 100000 characters.';
  if (s.length % 2 !== 0) return 's must have an even length.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  return null;
}

