function makeAntiPalindrome(s) {
  const chars = s.split('').sort();
  const n = chars.length;
  const half = n / 2;
  if (chars[half] !== chars[half - 1]) {
    return chars.join('');
  }
  const middle = chars[half - 1];
  let next = half;
  while (next < n && chars[next] === middle) {
    next++;
  }
  for (let j = half; j < n && chars[j] === chars[n - 1 - j]; j++) {
    if (next === n) {
      return '-1';
    }
    [chars[j], chars[next]] = [chars[next], chars[j]];
    next++;
  }
  return chars.join('');
}

