function makeAntiPalindrome(s) {
  // Walk every distinct rearrangement in lexicographic order; the first anti-palindrome wins.
  const a = [...s].sort();
  const n = a.length;
  const isAnti = () => {
    for (let i = 0; i < n; i++) if (a[i] === a[n - 1 - i]) return false;
    return true;
  };
  for (;;) {
    if (isAnti()) return a.join('');
    let i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;
    if (i < 0) return '-1';
    let k = n - 1;
    while (a[k] <= a[i]) k--;
    const t = a[i]; a[i] = a[k]; a[k] = t;
    const tail = a.slice(i + 1).reverse();
    for (let p = 0; p < tail.length; p++) a[i + 1 + p] = tail[p];
  }
}

