function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (from, to) => letters[from + Math.floor(rand() * (to - from))];
  if (size === 'small') {
    const n = 2 * (1 + Math.floor(rand() * 4));
    const start = Math.floor(rand() * 23);
    const width = 1 + Math.floor(rand() * 3);
    let s = '';
    for (let i = 0; i < n; i++) s += pick(start, start + width);
    return [s];
  }
  const n = 10000;
  const half = n / 2;
  const mode = Math.floor(rand() * 4);
  const dominant = Math.floor(rand() * 26);
  let count = 0;
  if (mode === 0) count = half;
  else if (mode === 1) count = half + 1;
  else if (mode === 2) count = Math.floor(rand() * half);
  const chars = [];
  for (let i = 0; i < count; i++) chars.push(letters[dominant]);
  while (chars.length < n) {
    const c = Math.floor(rand() * 26);
    if (mode !== 3 && c === dominant) continue;
    chars.push(letters[c]);
  }
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const t = chars[i]; chars[i] = chars[j]; chars[j] = t;
  }
  return [chars.join('')];
}
